// Add jitter when multiple jobs are due at the same tick to prevent
// thundering herd overload (see #58533). Default: 5s stagger
// across concurrent jobs, configurable via cron.missedJobStaggerMs.
const staggerMs = Math.max(0, state.deps.missedJobStaggerMs ?? DEFAULT_MISSED_JOB_STAGGER_MS);
const shouldStagger = dueJobs.length > 1 && staggerMs > 0;

const concurrency = Math.min(resolveRunConcurrency(state), Math.max(1, dueJobs.length));
const results: (TimedCronRunOutcome | undefined)[] = Array.from({ length: dueJobs.length });
let cursor = 0;

// Track job start times for staggered execution
const jobStartTimes: number[] = [];

const workers = Array.from({ length: concurrency }, async () => {
  for (;;) {
    const index = cursor++;
    if (index >= dueJobs.length) {
      return;
    }
    const due = dueJobs[index];
    if (!due) {
      return;
    }

    // Apply jitter for concurrent jobs (stagger start times)
    if (shouldStagger) {
      const jobDelayMs = index * staggerMs;
      if (jobDelayMs > 0) {
        state.deps.log.debug(
          { jobId: due.id, index, delayMs: jobDelayMs },
          "cron: staggering job start to prevent thundering herd",
        );
        await new Promise<void>((resolve) => setTimeout(resolve, jobDelayMs));
      }
      jobStartTimes[index] = state.deps.nowMs();
    }

    results[index] = await runDueJob(due);
  }
});
await Promise.all(workers);

